def discontinuity(self):
    """Index of the first step that does not start where the last ended.

    :attr:`states` reads the trace as one continuous walk -- it takes the
    source of the first step and the target of every step after it -- so the
    source states of the later steps never appear in it.  A trace that fails
    this check is therefore one whose reported states are not the states its
    transitions actually relate, and it is not an execution of anything.

    Returns:
        int or None: The index of the first disconnected step, or ``None``
        when the trace is a genuine walk.
    """
    for index in range(1, len(self.transitions)):
        if self.transitions[index - 1].dst != self.transitions[index].src:
            return index
    return None

def is_connected(self):
    """True when every step starts where the previous one ended."""
    return self.discontinuity() is None

